import{_ as t,o as i,c as a,a2 as e}from"./chunks/framework.Bqa2y7hU.js";const k=JSON.parse('{"title":"快速开始","description":"插件是什么、能做什么、需要准备什么环境，以及从新建 .cpp 到在群里跑通第一个插件的完整流程。","frontmatter":{"title":"快速开始","description":"插件是什么、能做什么、需要准备什么环境，以及从新建 .cpp 到在群里跑通第一个插件的完整流程。"},"headers":[],"relativePath":"plugin-dev/getting-started.md","filePath":"plugin-dev/getting-started.md","lastUpdated":1789795356000}'),d={name:"plugin-dev/getting-started.md"};function n(l,s,o,p,h,r){return i(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>这页解决一个问题：<strong>从零写出并跑通你的第一个 Xiaoyi_QQ_V4 插件</strong>。读完你能走完「新建源码 → 注册 → 编译 → 上传 → 装到机器人 → 群里测试」这条完整链路，并且知道为什么插件的 ABI 版本必须和框架匹配。</p><p>如果你已经写过 C++，全程大约十几分钟；不熟 C++ 也没关系，第一个插件不到 30 行。</p><h2 id="插件是什么" tabindex="-1">插件是什么 <a class="header-anchor" href="#插件是什么" aria-label="Permalink to &quot;插件是什么&quot;">​</a></h2><p>插件就是一个<strong>动态库文件</strong>（Linux 下 <code>.so</code>，Windows 下 <code>.dll</code>），在<strong>框架进程内</strong>被加载运行。</p><table tabindex="0"><thead><tr><th>事实</th><th>说明</th></tr></thead><tbody><tr><td>形态</td><td>一个动态库（<code>.so</code> / <code>.dll</code>），不是脚本、不需要解释器</td></tr><tr><td>语言</td><td>纯 C 或 C++（C++ 用官方 header-only SDK <code>plugin_sdk.hpp</code>）</td></tr><tr><td>运行方式</td><td>加载进框架进程，和框架共享地址空间，事件直接以函数回调的形式进来</td></tr><tr><td>接口</td><td>与框架之间靠一套<strong>冻结的 C ABI</strong> 通信，只有函数指针表和少量结构体</td></tr><tr><td>依赖</td><td>官方 SDK 只有一个头文件，无第三方依赖；插件自身的依赖需要静态链接进来</td></tr><tr><td>分发</td><td>上传插件包到控制台即热加载，不需要重启服务</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">因为跑在同一个进程里</p><p>插件里未捕获的崩溃（段错误、未定义行为）会影响整个框架进程。请做好参数判空与异常处理，只依赖 <code>BotHostApi</code> 提供的能力。</p></div><h2 id="插件能做什么" tabindex="-1">插件能做什么 <a class="header-anchor" href="#插件能做什么" aria-label="Permalink to &quot;插件能做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>用到的接口</th><th>展开页</th></tr></thead><tbody><tr><td>接收消息与事件</td><td><code>bot_plugin_on_message</code> 等回调</td><td><a href="/RuaBot.Doc/plugin-dev/events">处理事件</a></td></tr><tr><td>拦截与改写消息</td><td>三个 <code>bot_plugin_intercept_*</code> 回调</td><td><a href="/RuaBot.Doc/plugin-dev/interceptors">拦截器</a></td></tr><tr><td>回复与主动推送消息</td><td><code>send_reply</code> / <code>send_proactive</code></td><td><a href="/RuaBot.Doc/plugin-dev/messages">发送消息</a></td></tr><tr><td>撤回消息</td><td><code>recall</code> 或 <code>xubp.message.recall</code> 能力</td><td><a href="/RuaBot.Doc/plugin-dev/capabilities">调用平台能力</a></td></tr><tr><td>存数据</td><td>KV（键值）/ Blob（二进制）</td><td><a href="/RuaBot.Doc/plugin-dev/storage">存储与配置</a></td></tr><tr><td>每个机器人独立配置</td><td><code>setting_get</code> / <code>setting_set</code></td><td><a href="/RuaBot.Doc/plugin-dev/storage">存储与配置</a></td></tr><tr><td>调用平台能力（禁言、踢人、审批…）</td><td><code>has_capability</code> / <code>capability_invoke</code></td><td><a href="/RuaBot.Doc/plugin-dev/capabilities">调用平台能力</a></td></tr><tr><td>出站 HTTP 请求</td><td><code>http_get</code> / <code>http_request</code></td><td><a href="/RuaBot.Doc/reference/host-api">Host API</a></td></tr><tr><td>自带 Web 配置面板</td><td><code>bot_plugin_web_route</code> + <code>web/</code> 目录</td><td><a href="/RuaBot.Doc/plugin-dev/webui">插件 Web 面板</a></td></tr><tr><td>给机器人注册指令</td><td><code>register_command</code></td><td><a href="/RuaBot.Doc/reference/host-api">Host API</a></td></tr></tbody></table><h2 id="开发环境准备" tabindex="-1">开发环境准备 <a class="header-anchor" href="#开发环境准备" aria-label="Permalink to &quot;开发环境准备&quot;">​</a></h2><p>需要两样东西：</p><ol><li><strong>一个支持 C++17 的编译器</strong><ul><li>Linux：<code>g++</code>（<code>apt install -y build-essential</code>）</li><li>Windows：MSYS2 的 <code>g++</code>，或任意支持 <code>-shared</code> 的 C++17 编译器</li></ul></li><li><strong>SDK 头文件 <code>plugin_sdk.hpp</code></strong>（它会 <code>#include &quot;bot_plugin.h&quot;</code>，两个文件都要有） <ul><li>从框架源码的 <code>include/</code> 目录取得，放进你的工程目录</li><li>用云编译服务打包时不需要本地准备 SDK（详见 <a href="/RuaBot.Doc/plugin-dev/publish">云编译与上架</a>）</li></ul></li></ol><p>先确认编译器可用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 能看到版本号即可</span></span></code></pre></div><h2 id="_1-新建源码文件" tabindex="-1">1. 新建源码文件 <a class="header-anchor" href="#_1-新建源码文件" aria-label="Permalink to &quot;1. 新建源码文件&quot;">​</a></h2><p>新建一个目录，把 <code>plugin_sdk.hpp</code> 与 <code>bot_plugin.h</code> 放进去，然后新建 <code>mybot.cpp</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>myplugin/</span></span>
<span class="line"><span>├── plugin_sdk.hpp      # SDK（header-only，从框架源码 include/ 取得）</span></span>
<span class="line"><span>├── bot_plugin.h        # SDK 依赖的 C ABI 合同</span></span>
<span class="line"><span>└── mybot.cpp           # 你的插件源码</span></span></code></pre></div><h2 id="_2-注册插件" tabindex="-1">2. 注册插件 <a class="header-anchor" href="#_2-注册插件" aria-label="Permalink to &quot;2. 注册插件&quot;">​</a></h2><p>每个插件都要用注册宏声明自己的元数据（编码、名称、版本、作者、分类）：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;plugin_sdk.hpp&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 只用 SDK 头，别 include 框架内部头文件</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 插件被 @ 或私聊时的处理逻辑</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;C&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bot_plugin_on_message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BotMessageEvent</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> evt) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    bot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Message</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> m</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">evt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (m.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">is_group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;&amp;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> !</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">at_me</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 群里只在被 @ 时回复</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    m.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reply</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你好，我是插件&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 注册：编码 / 名称 / 版本 / 作者 / 分类</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BOT_REGISTER_PLUGIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mybot&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;我的插件&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你的名字&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tool&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><code>BOT_REGISTER_PLUGIN</code> 会展开出四个必需导出符号（<code>bot_plugin_abi_version</code> / <code>bot_plugin_meta</code> / <code>bot_plugin_init</code> / <code>bot_plugin_shutdown</code>），你不用自己写。想自定义优先级、订阅事件、拦截器、logo、配置项时改用 <code>BOT_REGISTER_PLUGIN_EX</code>，见 <a href="/RuaBot.Doc/reference/meta">插件元数据</a>。</p><h2 id="_3-编译成-so" tabindex="-1">3. 编译成 .so <a class="header-anchor" href="#_3-编译成-so" aria-label="Permalink to &quot;3. 编译成 .so&quot;">​</a></h2><p>用一条 <code>g++</code> 命令把源码编成动态库）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># -shared：产出动态库；-fPIC：位置无关代码；-std=c++17：C++17 标准</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -shared</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fPIC</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -std=c++17</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mybot.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mybot.so</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I.</span></span></code></pre></div><p>参数说明：<code>-I.</code> 指向 SDK 头文件所在目录；只要 <code>-o</code> 的文件名以 <code>.so</code> 结尾，上传时就会被识别（Windows 下产出 <code>.dll</code> 同样可以）。</p><h2 id="_4-上传到控制台" tabindex="-1">4. 上传到控制台 <a class="header-anchor" href="#_4-上传到控制台" aria-label="Permalink to &quot;4. 上传到控制台&quot;">​</a></h2><p>进入管理后台的<strong>插件上传</strong>页，把 <code>.so</code>（或带 Web 面板的 <code>.zip</code>）拖进去：</p><ul><li>上传时会<strong>自动从动态库里读取元数据</strong>（编码、名称、版本、作者、分类、logo、设置项），不需要你手填；</li><li><strong>上传即热加载</strong>，不需要重启服务；</li><li>上传成功的插件会出现在「插件市场」，可随时启停或隐藏。</li></ul><h2 id="_5-装到机器人" tabindex="-1">5. 装到机器人 <a class="header-anchor" href="#_5-装到机器人" aria-label="Permalink to &quot;5. 装到机器人&quot;">​</a></h2><p>在<strong>插件市场</strong>里找到刚上传的插件，点「安装」，选择要安装到的机器人。安装后每台机器人可以<strong>单独</strong>设置：</p><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td>启用 / 停用</td><td>该机器人是否加载这个插件</td></tr><tr><td>优先级</td><td>数字越小越先收到事件（默认 1000）</td></tr><tr><td>Incoming / Outgoing / AfterSend 开关</td><td>该机器人是否启用这个插件的三层拦截器</td></tr></tbody></table><p>上传后如果想改这些，进<strong>机器人详情页 → 插件 Tab → 配置</strong>。</p><h2 id="_6-在群里测试" tabindex="-1">6. 在群里测试 <a class="header-anchor" href="#_6-在群里测试" aria-label="Permalink to &quot;6. 在群里测试&quot;">​</a></h2><p>把机器人拉进一个群（或在私聊里），发一条消息：</p><ul><li>私聊：插件会回「你好，我是插件」；</li><li>群里：需要 <strong>@ 机器人</strong> 才会触发（这是 QQ 官方机器人的默认行为：未获授权「接收所有消息」时只能收到 @ 机器人的消息）。</li></ul><p>没反应时，去<strong>机器人详情页 → 日志 Tab</strong> 看有没有插件相关日志，或对照 <a href="/RuaBot.Doc/plugin-dev/debugging">调试与排错</a>。</p><div class="warning custom-block"><p class="custom-block-title">ABI 版本必须匹配</p><p>插件的 ABI 版本由 SDK 头文件决定，框架按 <code>major</code> 一致、插件 <code>minor</code> 不高于框架 <code>minor</code> 的规则协商：<strong>major 不一致直接拒绝加载，插件 minor 比框架新也拒绝加载</strong>。所以你升级了 SDK 或框架后，可能需要重新编译插件。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/plugin-dev/minimal">最小示例</a>：把框架自带的最短插件逐行讲清楚</li><li><a href="/RuaBot.Doc/plugin-dev/structure">目录结构与打包</a>：插件包该长什么样、上传时哪些文件会被采用</li><li><a href="/RuaBot.Doc/plugin-dev/abi">ABI 与兼容规则</a>：什么时候必须重新编译插件</li></ul>`,39)])])}const g=t(d,[["render",n]]);export{k as __pageData,g as default};
